'use strict';
const {nextPriority,orderExercises,orderedForWorkout,priorityLabel,priorityOptions}=globalThis.FormaPlanner;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=0)=>new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:d}).format(Number(n)||0);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const dateText=(v,short=false)=>new Date(typeof v==='number'?v*1000:v+'T12:00:00').toLocaleDateString('cs-CZ',{day:'numeric',month:short?'numeric':'long',...(short?{}:{year:'numeric'})});
const icons={home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',lift:'M6 5v14 M3 8v8 M18 5v14 M21 8v8 M6 12h12',food:'M5 3v7c0 2 4 2 4 0V3 M7 3v18 M18 3c-4 4-4 9 0 9V3 M18 12v9',users:'M16 21v-3c0-5-12-5-12 0v3 M10 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M18 4c4 1 4 6 0 7 M20 15c2 1 2 4 2 6',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-2c0-7 16-7 16 0v2',arrow:'M5 19 19 5 M5 5h14v14',plus:'M12 5v14 M5 12h14',check:'m5 12 4 4L19 6',chart:'M4 3v17h17 M7 15l5-5 4 2 5-7',trophy:'M8 3h8v7a4 4 0 0 1-8 0z M8 5H4v3c0 3 4 4 4 4 M16 5h4v3c0 3-4 4-4 4 M12 14v6 M8 21h8',drop:'M12 2S5 11 5 15a7 7 0 0 0 14 0c0-4-7-13-7-13',clock:'M12 4a8 8 0 1 0 0 16 8 8 0 0 0 0-16 M12 7v5l4 2',calendar:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16',camera:'M3 7h4l2-3h6l2 3h4v14H3z M12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8',heart:'M12 21 3 12C-3 3 8-1 12 6 16-1 27 3 21 12z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',bolt:'m13 2-9 12h7l-1 8 10-13h-7z',lock:'M6 10V7a6 6 0 0 1 12 0v3 M4 10h16v12H4z',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',logout:'M9 4H3v16h6 M9 12h12 m-5-5 5 5-5 5',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16',flag:'M5 22V3h14l-3 5 3 5H5'};
const icon=n=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.bolt}"/></svg>`;
let state=null,config={},tab='home',plan='Upper',selectedDay=today(),community=null,offline=false,authRegister=false,restEnd=0,modalReturn=null,toastTimer,photoId=null,bodyPhotoId=null,lastReminder='',selectedPriorities={};
let loading=false;
const cacheKey=id=>'forma-state-'+id, queueKey=id=>'forma-queue-'+id;
const queue=()=>{try{return JSON.parse(localStorage.getItem(queueKey(state.user.id))||'[]');}catch{return [];}};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
async function api(path,data){
 let r;
 try{r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:data instanceof FormData?{}:data===undefined?{}:{'Content-Type':'application/json'},body:data instanceof FormData?data:data===undefined?undefined:JSON.stringify(data),credentials:'same-origin'});}catch(e){e.network=true;throw e;}
 let d;try{d=await r.json();}catch{throw new Error('Server vrátil neplatnou odpověď.');}
 if(!r.ok){const e=new Error(d.error||'Akce se nepodařila.');e.status=r.status;throw e;}
 return d;
}
function saveCache(){try{localStorage.setItem(cacheKey(state.user.id),JSON.stringify(state));localStorage.setItem('forma-last-user',state.user.id);}catch{toast('Úložiště telefonu je plné. Připoj se pro uložení na server.');}}
async function refresh(){
 try{const s=await api('state');state=s;offline=false;saveCache();return true;}
 catch(e){if(e.status===401){state=null;renderAuth();throw e;}offline=!!e.network;throw e;}
}
async function sync(){
 if(!state)return;
 const entries=queue();if(!entries.length)return;
 for(const entry of entries){
  try{await api('set',entry);const q=queue().filter(x=>x.id!==entry.id);localStorage.setItem(queueKey(state.user.id),JSON.stringify(q));}
  catch(e){if(!e.network)toast('Čekající série: '+e.message);return;}
 }
 await refresh();toast('Série jsou synchronizované.');
}
const allSets=()=>state?[...queue().map(s=>({...s,user_id:state.user.id,pending:true})),...state.sets]:[];
const completed=()=>state.workouts.filter(w=>w.ended);
const activeWorkout=()=>state.workouts.find(w=>!w.ended);
const exercise=id=>state.exercises.find(e=>e.id===id);
const exSets=id=>allSets().filter(s=>s.exercise_id===id).sort((a,b)=>b.created-a.created);
const totalWeight=s=>Number(s.weight)+Number(s.extra||0);
const performance=(s,e)=>e?.mode==='stack'?`${fmt(s.reps)} × celý zásobník`:`${fmt(totalWeight(s),1)} kg × ${fmt(s.reps)}`;
const lastFor=e=>exSets(e.id)[0]||e;
function macroTotal(day=selectedDay){return state.meals.filter(m=>m.day===day).reduce((a,m)=>{['kcal','protein','carbs','fat'].forEach(k=>a[k]+=Number(m[k]));return a;},{kcal:0,protein:0,carbs:0,fat:0});}
function weekData(){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const day=new Date(d);day.setDate(d.getDate()+i);return {date:day.toLocaleDateString('sv-SE'),count:completed().filter(w=>new Date(w.started*1000).toLocaleDateString('sv-SE')===day.toLocaleDateString('sv-SE')).length};});}
function levelData(){const n=completed().length,days=new Set(completed().map(w=>new Date(w.started*1000).toLocaleDateString('sv-SE'))).size;const xp=n*100+days*25;return {xp,level:1+Math.floor(xp/500),progress:xp%500,n,days};}
function chart(points,label='kg'){
 if(!points.length)return `<div class="empty">${icon('chart')}<p>První záznam je začátek tvého grafu.</p></div>`;
 const values=points.map(p=>p.value),max=Math.max(...values)*1.08||1,min=Math.max(0,Math.min(...values)*.85),range=max-min||1;
 const x=i=>points.length===1?260:44+i*456/(points.length-1),y=v=>140-(v-min)/range*110;
 return `<svg class="chart" viewBox="0 0 540 180" role="img" aria-label="${esc(label)}: ${points.map(p=>esc(p.label)+' '+fmt(p.value,1)).join(', ')}">${[0,.5,1].map(f=>`<line x1="40" y1="${30+f*110}" x2="510" y2="${30+f*110}"/><text x="0" y="${34+f*110}">${fmt(max-f*range)}</text>`).join('')}<polyline points="${points.map((p,i)=>x(i)+','+y(p.value)).join(' ')}"/>${points.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.value)}" r="5"/><title>${esc(p.label)}: ${fmt(p.value,1)} ${esc(label)}</title>`).join('')}<text x="40" y="171">${esc(points[0].label)}</text><text x="500" y="171" text-anchor="end">${esc(points[points.length-1].label)} · ${esc(label)}</text></svg>`;
}
function empty(title,description,action,label){return `<div class="empty">${icon('bolt')}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action?`<button class="secondary" data-action="${action}">${esc(label)}</button>`:''}</div>`;}
function renderAuth(){
 $('#app').innerHTML=`<main class="auth"><section class="auth-story"><div class="brand">F<span>↗</span>RMA</div><div><div class="eyebrow">TVŮJ PROGRES. TVOJE TEMPO.</div><h1>Silnější.<br>Každým<br><span class="accent">návratem.</span></h1><p>Trénink, jídlo a tvoje parta. Jeden prostor pro všechno, co tě posouvá.</p><div class="auth-feature"><span>↗ Vlastní rekordy</span><span>◷ Rychlý zápis</span><span>⌁ Tvoje parta</span></div></div><small>Malé kroky. Skutečný progres.</small></section><section class="auth-form"><div class="eyebrow">VÍTEJ VE FORMA</div><h2>${authRegister?'Začíná to tebou.':'Zpátky ve svojí formě.'}</h2><p>${authRegister?'Vytvoř si soukromý účet. Sdílet budeš jen to, co chceš.':'Přihlas se a pokračuj tam, kde jsi skončil.'}</p><form data-form="auth">${authRegister?'<label>Přezdívka<input name="name" required maxlength="50" autocomplete="nickname" placeholder="Jak ti říká parta?"></label>':''}<label>E-mail<input name="email" type="email" required autocomplete="email" placeholder="ty@priklad.cz" maxlength="200"></label><label>Heslo<input name="password" type="password" minlength="10" maxlength="128" required autocomplete="${authRegister?'new-password':'current-password'}" placeholder="Alespoň 10 znaků"></label><p class="form-error hidden" role="alert"></p><button class="primary full" type="submit">${authRegister?'Vytvořit účet':'Přihlásit se'} ${icon('arrow')}</button></form><div class="auth-switch">${authRegister?'Už máš účet?':'Ještě nemáš účet?'} <button data-action="auth-switch">${authRegister?'Přihlásit se':'Vytvořit účet'}</button></div><p class="field-help section-gap">E-mail + heslo jsou dostupné. Google a Apple přihlášení zatím nejsou připojené. E-mail se v této verzi neověřuje a obnova zapomenutého hesla není dostupná.</p><button class="ghost" data-action="install">Jak přidat na plochu</button></section></main>`;
}
function render(){
 if(!state)return renderAuth();
 const user=state.user,lv=levelData();
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">F<span>↗</span>RMA</div><nav class="nav" aria-label="Hlavní navigace">${[['home','Dnes','home'],['plans','Plány','flag'],['train','Trénink','lift'],['food','Jídlo','food'],['friends','Parta','users'],['profile','Profil','user']].map(([id,label,ic])=>`<button data-action="tab" data-id="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="side-bottom"><div class="notice">Tvůj jediný soupeř?<br><b>Ty, o trénink zpátky.</b></div><div class="mini-profile"><div class="avatar">${esc(user.name[0]?.toUpperCase())}</div><div><b>${esc(user.name)}</b><div class="meta-line">${user.settings.gamification?'Úroveň '+lv.level:'Vlastní tempo'}</div></div></div><button class="ghost" data-action="install">${icon('download')} Přidat na plochu</button></div></aside><main class="main"><header class="topbar"><span class="eyebrow">MALÉ KROKY. SKUTEČNÝ PROGRES.</span><div class="brand mobile-brand">F<span>↗</span>RMA</div><div class="row"><span class="pill"><span class="dot" style="${offline?'background:var(--orange)':''}"></span>${offline?'Bez připojení':queue().length?'Čeká na uložení':'Připojeno'}</span><button class="circle-btn" data-action="install" aria-label="Návod k instalaci">${icon('download')}</button></div></header>${offline?'<div class="offline-notice">Jsi offline. Série v otevřeném tréninku ukládáme do tohoto zařízení. Ostatní změny potřebují připojení.</div>':''}${queue().length?`<div class="offline-notice">${queue().length} sérií čeká na synchronizaci. <button class="ghost" data-action="sync">Zkusit teď</button></div>`:''}<div id="page">${({home:renderHome,plans:renderPlans,train:renderTrain,food:renderFood,friends:renderFriends,profile:renderProfile}[tab])()}</div></main></div>`;
 timerRender();
}
function title(h,p,action=''){return `<div class="page-title"><div><h1>${h}</h1><p>${p}</p></div>${action}</div>`;}
function nutrientCard(day=today()){
 const t=macroTotal(day),s=state.user.settings;
 return `<section class="card"><div class="card-header"><h2>Palivo na dnešek</h2>${icon('food')}</div><div class="ring-wrap"><div class="ring" style="--pct:${Math.min(100,t.kcal/s.kcal*100)}%"><div><div class="number">${fmt(t.kcal)}</div><small>z ${fmt(s.kcal)} kcal</small></div></div><div><small>${t.kcal<=s.kcal?'Do cíle zbývá':'Nad cílem'}</small><div class="number">${fmt(Math.abs(s.kcal-t.kcal))}<small> kcal</small></div><span class="meta-line">Tvůj nastavitelný denní cíl</span></div></div><div class="grid">${[['protein','Bílkoviny'],['carbs','Sacharidy'],['fat','Tuky']].map(([key,name])=>`<div class="macro"><div class="row between"><b>${name}</b><small>${fmt(t[key])} / ${fmt(s[key])} g</small></div><div class="progress"><span style="width:${Math.min(100,s[key]?t[key]/s[key]*100:0)}%"></span></div></div>`).join('')}</div><button class="secondary full section-gap" data-action="meal">${icon('plus')} Přidat jídlo</button></section>`;
}
function renderHome(){
 const w=weekData(),count=w.reduce((a,d)=>a+d.count,0),s=state.user.settings,lv=levelData(),active=activeWorkout(),last=completed()[0],plans=[...new Set(state.exercises.map(e=>e.plan))];
 return title(`Ahoj, ${esc(state.user.name)}<span class="accent">.</span>`,'Dnes je dobrý den posunout se o kousek.')+`<div class="grid dash"><div class="stack"><section class="card hero-card"><div class="eyebrow">${active?'MÁŠ TO ROZJETÉ':'TVŮJ DALŠÍ KROK'}</div><h2>${active?'Ještě jedno<br>dobré opakování.':'Tvoje další<br>lepší verze.'}</h2><p>${active?esc(active.name)+' · trénink je rozpracovaný':last?'Posledně '+esc(last.name)+'. Dnes navážeš podle sebe.':'Začni tréninkem. Každý záznam ti příště ukáže cestu.'}</p><button class="primary" data-action="${state.exercises.length?'tab':'template'}" data-id="train">${active?'Pokračovat v tréninku':state.exercises.length?'Jdeme cvičit':'Načíst Upper / Lower'} ${icon('arrow')}</button></section><div class="grid cols3"><div class="card metric"><div class="eyebrow">Tento týden</div><div class="number">${count}<small> / ${fmt(s.weekly)}</small></div><small>dokončených tréninků</small></div><div class="card metric"><div class="eyebrow">Od začátku</div><div class="number">${completed().length}</div><small>návratů do fitka</small></div><div class="card metric"><div class="eyebrow">Moje cviky</div><div class="number">${state.exercises.length}</div><small>${plans.length} tréninkové plány</small></div></div><section class="card"><div class="card-header"><h2>Tvoje pravidelnost</h2><span class="pill">${count>=s.weekly?'Cíl splněn ✓':'Vlastní tempo'}</span></div><div class="week">${w.map((d,i)=>`<div>${['PO','ÚT','ST','ČT','PÁ','SO','NE'][i]}<span class="${d.count?'done':''} ${d.date===today()?'today':''}">${d.count?'✓':Number(d.date.slice(-2))}</span></div>`).join('')}</div><p class="meta-line section-gap" style="margin-bottom:0">Cíl ${fmt(s.weekly)} tréninky za týden. Dny odpočinku jsou součást plánu.</p></section><section class="card"><div class="card-header"><h2>Poslední tréninky</h2><button class="ghost" data-action="history">Historie ↗</button></div>${completed().slice(0,3).map(w=>`<button class="history-row full" data-action="workout-detail" data-id="${w.id}"><span>${esc(w.name)}<small style="display:block">${dateText(w.started,true)}</small></span><b>${allSets().filter(x=>x.workout_id===w.id).length} sérií ↗</b></button>`).join('')||empty('Zatím čistý list','Tvoje první dokončené cvičení se objeví tady.')}</section></div><div class="stack">${nutrientCard()}<section class="card"><div class="card-header"><h2>Nezapomeň se napít</h2>${icon('drop')}</div><div class="row between"><div class="number">${fmt(waterToday()/1000,2)}<small> / ${fmt(s.water/1000,1)} l</small></div><button class="circle-btn" data-action="water" data-ml="250" aria-label="Přidat 250 ml">${icon('plus')}</button></div><div class="progress section-gap"><span style="width:${Math.min(100,s.water?waterToday()/s.water*100:0)}%"></span></div><div class="row section-gap"><button class="secondary" data-action="water" data-ml="250">+ 250 ml</button><button class="ghost" data-action="water" data-ml="-250">− 250 ml</button></div></section>${s.gamification?`<section class="xp"><div class="row between"><div><div class="eyebrow">ROSTEŠ S KAŽDÝM NÁVRATEM</div><b>Úroveň ${lv.level}</b></div>${icon('trophy')}</div><div class="progress section-gap"><span style="width:${lv.progress/5}%"></span></div><p class="meta-line" style="margin:10px 0 0">${lv.xp} XP · ${500-lv.progress} XP do další úrovně</p></section>`:''}</div></div>`;
}
function waterToday(){return state.water.find(w=>w.day===today())?.ml||0;}
function chosenPriority(planName){return selectedPriorities[planName]||nextPriority(planName,state.workouts);}
function sequenceFor(planName){const active=activeWorkout();return active&&active.name===planName?orderedForWorkout(state.exercises,active):orderExercises(state.exercises,planName,chosenPriority(planName));}
function renderPlans(){
 const plans=[...new Set(state.exercises.map(e=>e.plan))],active=activeWorkout();
 if(!plans.length)return title('Trénink podle tebe.','Začni připravenou šablonou a potom si ji uprav.')+empty('Upper / Lower je připravený na jedno klepnutí','Váhy a opakování jsou pouze výchozí hodnoty.','template','Načíst Upper / Lower');
 return title('Plán, který drží tvar.','Priorita se střídá, pořadí se při startu uloží a zůstane stejné.',`<button class="secondary" data-action="exercise">${icon('plus')} Cvik</button>`)+`<div class="plan-grid">${plans.map(planName=>{const options=priorityOptions(planName),priority=active&&active.name===planName?active.priority:chosenPriority(planName),items=sequenceFor(planName);return `<section class="card plan-card ${active&&active.name===planName?'active-plan':''}"><div class="card-header"><div><div class="eyebrow">${active&&active.name===planName?'ROZPRACOVÁNO':'DALŠÍ ROTACE'}</div><h2>${esc(planName)}</h2></div><span class="pill">${esc(priorityLabel(priority))}</span></div>${options.length?`<div class="priority-picker" role="group" aria-label="Priorita ${esc(planName)}">${options.map(value=>`<button data-action="priority" data-plan="${esc(planName)}" data-id="${value}" class="${priority===value?'active':''}" ${active?'disabled':''}>${esc(priorityLabel(value).replace(' první',''))}</button>`).join('')}</div>`:'<p class="meta-line">Vlastní plán zachovává tvoje pořadí.</p>'}<ol class="plan-sequence">${items.map((exercise,index)=>`<li><span>${index+1}</span><div><b>${esc(exercise.name)}</b><small>${esc(exercise.note||exercise.plan)}</small></div></li>`).join('')}</ol><button class="primary full" data-action="open-plan" data-id="${esc(planName)}" ${active&&active.name!==planName?'disabled':''}>${active&&active.name===planName?'Pokračovat':'Otevřít trénink'} ${icon('arrow')}</button></section>`;}).join('')}</div><div class="notice">${icon('lock')} Priorita mění pouze pořadí. Cviky, váhy ani tvoje historie se nemažou.</div>`;
}
function renderTrain(){
 const plans=[...new Set(state.exercises.map(e=>e.plan))];if(!plans.includes(plan)&&plans.length)plan=plans[0];const active=activeWorkout();if(active)plan=active.name;const sequence=sequenceFor(plan),priority=active?.priority||chosenPriority(plan);
 return title('O kousek silnější.','Minulý výkon máš před očima. Další je na tobě.',`<button class="secondary" data-action="exercise">${icon('plus')} Cvik</button>`)+`${active?`<div class="workout-banner"><div><b>${esc(active.name)} · ${esc(priorityLabel(priority))}</b><div class="meta-line">${allSets().filter(s=>s.workout_id===active.id).length} sérií · pořadí uloženo · průběžně ukládáno</div></div><button class="primary" data-action="finish">Dokončit ✓</button></div>`:''}<div class="tabs">${plans.map(p=>`<button data-action="plan" data-id="${esc(p)}" class="${p===plan?'active':''}" ${active?'disabled':''}>${esc(p)}</button>`).join('')}<button data-action="history">${icon('calendar')} Historie</button></div><section class="card"><div class="card-header"><div><h2>${esc(plan)}</h2><span class="meta-line">${esc(priorityLabel(priority))}</span></div>${state.exercises.length&&!active?`<button class="primary" data-action="start">Začít trénink ${icon('arrow')}</button>`:''}</div>${state.exercises.length?sequence.map((e,index)=>{const last=lastFor(e),logged=exSets(e.id).length;return `<div class="exercise"><span class="exercise-order">${index+1}</span><button class="exercise-icon" data-action="exercise-detail" data-id="${e.id}" aria-label="Historie ${esc(e.name)}">${icon('lift')}</button><div class="exercise-info"><h3><button data-action="exercise-detail" data-id="${e.id}" style="padding:0;text-align:left">${esc(e.name)}</button></h3><small>${e.mode==='single'?'Na jednu činku / stranu':e.mode==='added'?'Přídavná zátěž':e.mode==='stack'?'Celý zásobník · kg neznámé':e.extra?`${fmt(e.weight)} kg základ + ${fmt(e.extra)} kg navíc`:'Celková zátěž'}</small></div><div class="performance"><b>${esc(performance(last,e))}</b><small>${logged?'Poslední série':'Výchozí hodnota plánu'}</small></div><button class="circle-btn" data-action="log-set" data-id="${e.id}" aria-label="Zapsat sérii ${esc(e.name)}">${icon('plus')}</button></div>`;}).join(''):empty('Tvůj tréninkový prostor','Načti připravený Upper / Lower, nebo přidej vlastní cvik. Výchozí váhy si před použitím uprav.','template','Načíst Upper / Lower')}</section><div class="notice">${icon('lock')} Záznamy jsou soukromé. Sdílení zapneš v profilu a jednotlivý trénink zveřejníš při dokončení.</div>`;
}
function renderFood(){
 const meals=state.meals.filter(m=>m.day===selectedDay),t=macroTotal(),s=state.user.settings;
 return title('Dobré palivo.','Jídlo, které podporuje tvoje cíle.',`<button class="primary" data-action="meal">${icon('plus')} Jídlo</button>`)+`<div class="row between wrap" style="margin-bottom:20px"><div class="row"><button class="circle-btn" data-action="day" data-id="-1" aria-label="Předchozí den">‹</button><label><span class="sr-only">Datum jídelního deníku</span><input type="date" id="food-day" value="${selectedDay}"></label><button class="circle-btn" data-action="day" data-id="1" aria-label="Následující den">›</button></div><div class="row"><button class="ghost" data-action="favorites">${icon('heart')} Oblíbené</button><button class="ghost" data-action="copy-meals">${icon('book')} Včerejší jídla</button></div></div><div class="grid cols3"><div class="card metric"><div class="eyebrow">Energie</div><div class="number">${fmt(t.kcal)}<small> kcal</small></div><small>Cíl ${fmt(s.kcal)} kcal</small></div><div class="card metric"><div class="eyebrow">Bílkoviny</div><div class="number">${fmt(t.protein)}<small> g</small></div><small>Cíl ${fmt(s.protein)} g</small></div><div class="card metric"><div class="eyebrow">Sacharidy / tuky</div><div class="number">${fmt(t.carbs)}<small> / ${fmt(t.fat)} g</small></div><small>Cíl ${fmt(s.carbs)} / ${fmt(s.fat)} g</small></div></div><div class="grid dash section-gap"><section class="card"><div class="card-header"><h2>${selectedDay===today()?'Dnešní deník':dateText(selectedDay)}</h2><span class="pill">${meals.length} jídel</span></div>${meals.map(m=>`<div class="meal">${m.photo_id?`<img class="meal-thumb" src="/api/photo/${m.photo_id}" alt="${esc(m.name)}" loading="lazy">`:`<div class="meal-thumb">${icon('food')}</div>`}<div class="meal-info"><h3><button data-action="meal-detail" data-id="${m.id}" style="padding:0;text-align:left">${esc(m.name)} ${m.favorite?'♡':''}</button></h3><small>B ${fmt(m.protein)} · S ${fmt(m.carbs)} · T ${fmt(m.fat)} g</small></div><div class="meal-kcal">${fmt(m.kcal)}<small>kcal</small></div></div>`).join('')||empty('Co bylo dobrého?','Přidej jídlo ručně, z databáze nebo s fotografií.','meal','Přidat první jídlo')}</section><div class="stack"><section class="card"><div class="exercise-icon">${icon('camera')}</div><h2 class="section-gap">Vyfoť. Uprav. Hotovo.</h2><p class="muted" style="font-size:13px">Fotografie, krátký popis porce a upravitelný odhad. Jídlo zůstává soukromé.</p><button class="secondary full" data-action="meal-photo">${icon('camera')} Vyfotit jídlo</button><p class="meta-line" style="margin:12px 0 0">${config.ai?'AI je připojená. Odhad vždy zkontroluj.':'AI není připojená. Fotku můžeš uložit a hodnoty zadat ručně.'}</p></section><section class="card"><h2>Posledních 7 dní</h2>${foodChart()}<p class="meta-line">Zapsané kalorie za den. Prázdný den neznamená nulový skutečný příjem.</p></section></div></div>`;
}
function foodChart(){const pts=[];for(let i=6;i>=0;i--){const d=new Date(selectedDay+'T12:00:00');d.setDate(d.getDate()-i);const day=d.toLocaleDateString('sv-SE');if(state.meals.some(m=>m.day===day))pts.push({label:dateText(day,true),value:macroTotal(day).kcal});}return chart(pts,'kcal');}
function renderFriends(){
 if(!community)return title('Líp to jde spolu.','Sdílej úspěchy s lidmi, kteří ti fandí.')+`<section class="card">${empty('Tvoje parta','Načítáme sdílené aktivity.','load-community','Načíst partu')}</section>`;
 const friends=community.friends,feed=community.feed,ranking=friends.filter(f=>f.share).sort((a,b)=>b.count-a.count);
 return title('Líp to jde spolu.','Tvoje parta. Vaše malé i velké výhry.',`<button class="primary" data-action="invite">${icon('plus')} Pozvat</button>`)+`<div class="grid dash"><div class="stack"><section class="card"><div class="card-header"><h2>Z vaší party</h2><button class="ghost" data-action="load-community">Obnovit ↻</button></div>${feed.length?feed.map(w=>`<article class="card feed-item"><div class="row"><div class="avatar">${esc(w.author[0])}</div><div><h3>${esc(w.author)}</h3><small>${dateText(w.started,true)} · ${esc(w.name)}</small></div></div><div class="feed-stats"><span>${w.sets.length} sérií</span><span>${new Set(w.sets.map(s=>s.name)).size} cviků</span></div>${w.sets.slice(0,5).map(s=>`<div class="history-row"><span>${esc(s.name)}</span><b>${esc(performance(s,s))}</b></div>`).join('')}<div class="row between section-gap"><button class="secondary" data-action="react" data-id="${w.id}">${w.liked?'♥':'♡'} ${w.likes}</button><button class="ghost" data-action="copy-workout" data-id="${w.id}">Převzít jako plán ↗</button><button class="ghost" data-action="comment" data-id="${w.id}">Komentovat</button></div>${w.comments.map(c=>`<div class="comment"><b>${esc(c.name)}</b> ${esc(c.text)}</div>`).join('')}</article>`).join(''):empty('Tady začnou vaše příběhy','Pozvi kamaráda. Uvidíte jen dokončené tréninky, které si navzájem nasdílíte.','invite','Pozvat kamaráda')}</section></div><div class="stack"><section class="card"><h2>Kamarádi <small>${friends.length}</small></h2>${friends.map(f=>`<div class="history-row"><div class="row"><div class="avatar">${esc(f.name[0])}</div><div><b>${esc(f.name)}</b><div class="meta-line">${f.share?'Sdílí tréninky':'Soukromý profil'}</div></div></div><button class="ghost danger" data-action="remove-friend" data-id="${f.id}">Odebrat</button></div>`).join('')||'<p class="muted">První pozvánka je na tobě.</p>'}<button class="secondary full section-gap" data-action="join">Přijmout pozvánku</button></section>${state.user.settings.gamification?`<section class="card"><div class="card-header"><h2>Vaše pravidelnost</h2>${icon('trophy')}</div><p class="meta-line">Počet dobrovolně sdílených tréninků za celou dobu. Soukromá aktivita se nezapočítává.</p>${ranking.map((f,i)=>`<div class="history-row"><span>${i+1}. ${esc(f.name)}</span><b>${f.count}</b></div>`).join('')||'<p class="muted">Zatím bez sdílených výkonů.</p>'}<button class="secondary full section-gap" data-action="challenge">Vytvořit společnou výzvu</button>${challengeCards()}</section>`:''}<div class="notice">${icon('lock')} Jídla, fotografie postavy a tělesné míry zůstávají v této verzi vždy soukromé.</div></div></div>`;
}
function challengeCards(){return (community?.challenges||[]).map(c=>{const joined=c.members.some(m=>m.id===state.user.id),ended=c.ends*1000<Date.now();return `<div class="xp section-gap"><h3>${esc(c.title)}</h3><p class="meta-line">${esc(c.author)} · cíl ${c.target} tréninků · do ${dateText(c.ends,true)}</p>${c.members.map(m=>`<div class="history-row"><span>${esc(m.name)}</span><b>${m.count} / ${c.target} ${m.count>=c.target?'✓':''}</b></div>`).join('')}<button class="ghost" data-action="${joined?'challenge-leave':'challenge-join'}" data-id="${c.id}" ${ended&&!joined?'disabled':''}>${joined?'Opustit výzvu':ended?'Výzva skončila':'Přidat se k výzvě'}</button></div>`;}).join('');}
function badges(){const l=levelData(),total=allSets().length,defs=[['První krok',l.n>=1,'1 dokončený trénink'],['V rytmu',l.n>=10,'10 tréninků'],['Zvyk vítězí',l.n>=25,'25 tréninků'],['Stovka',total>=100,'100 zapsaných sérií'],['Dlouhá hra',l.n>=50,'50 tréninků'],['Základ síly',state.exercises.length>=10,'10 vlastních cviků'],['Palivo',new Set(state.meals.map(m=>m.day)).size>=7,'7 dní s deníkem'],['Ve dvou',community?.friends?.length>=1,'Kamarád v partě']];return `<div class="badges">${defs.map(([name,on,desc])=>`<div class="badge ${on?'unlocked':''}" title="${esc(desc)}">${icon('trophy')}<div><b>${name}</b></div><small>${desc}</small></div>`).join('')}</div>`;}
function renderProfile(){
 const u=state.user,l=levelData(),m=state.metrics.filter(m=>m.weight),last=m[m.length-1],s=u.settings;
 return title('Tvoje vlastní cesta.','Údaje, cíle a pravidla sdílení.',`<button class="secondary" data-action="settings">${icon('settings')} Nastavení</button>`)+`<div class="grid dash"><div class="stack"><section class="card"><div class="profile-cover"><div class="avatar">${esc(u.name[0])}</div><div><h2>${esc(u.name)}</h2><small>${esc(u.email)}</small><div class="meta-line">${s.share?'Tréninky můžeš sdílet s partou':'Soukromý profil · sdílení vypnuto'}</div></div></div>${s.gamification?`<div class="xp section-gap"><div class="row between"><div><div class="eyebrow">TVŮJ POSTUP</div><div class="xp-level">${l.level}<small style="font-size:14px;letter-spacing:0">. úroveň</small></div></div><b>${l.xp} XP</b></div><div class="progress"><span style="width:${l.progress/5}%"></span></div><p class="meta-line" style="margin:12px 0 0">100 XP za trénink + 25 XP za aktivní den. Odpočinek nic nemaže.</p></div>`:''}</section><section class="card"><div class="card-header"><h2>Tělesný progres</h2><button class="secondary" data-action="metric">${icon('plus')} Záznam</button></div>${last?`<div class="number">${fmt(last.weight,1)}<small> kg · ${dateText(last.day,true)}</small></div>`:''}${chart(m.slice(-30).map(x=>({label:dateText(x.day,true),value:x.weight})))}${state.metrics.slice(-5).reverse().map(x=>`<div class="history-row"><span>${dateText(x.day,true)}</span><b>${x.weight?fmt(x.weight,1)+' kg':''} ${x.waist?'· pas '+fmt(x.waist,1)+' cm':''}</b>${x.photo_id?`<button class="ghost" data-action="view-photo" data-id="${x.photo_id}">${icon('camera')}</button>`:''}</div>`).join('')}<p class="meta-line">Hodnoty a fotky vidíš pouze ty.</p></section>${s.gamification?`<section class="card"><h2>Milníky, které zůstávají</h2>${badges()}</section>`:''}</div><div class="stack"><section class="card"><h2>Moje cíle</h2>${[['Energie',fmt(s.kcal)+' kcal'],['Bílkoviny',fmt(s.protein)+' g'],['Sacharidy',fmt(s.carbs)+' g'],['Tuky',fmt(s.fat)+' g'],['Voda',fmt(s.water/1000,1)+' l'],['Trénink',fmt(s.weekly)+'× týdně']].map(([name,value])=>`<div class="history-row"><span>${name}</span><b>${value}</b></div>`).join('')}<button class="secondary full section-gap" data-action="settings">Upravit cíle</button><p class="meta-line section-gap">Výchozí hodnoty jsou pouze upravitelná šablona. Kalorie z tréninku automaticky nepřičítáme.</p></section><section class="card"><h2>Malé užitečné věci</h2><div class="stack"><button class="secondary full" data-action="plates">${icon('lift')} Kalkulačka kotoučů</button><button class="secondary full" data-action="recipe">${icon('book')} Vlastní recept</button><button class="secondary full" data-action="install">${icon('download')} Přidat na plochu</button><a class="secondary full" href="/api/export" download>${icon('download')} Export všech záznamů</a><button class="secondary full" data-action="logout">${icon('logout')} Odhlásit se</button><button class="ghost danger" data-action="delete-account">Smazat účet a všechna data</button></div></section><p class="meta-line">FORMA 2.0 · E-mailové účty, stabilní plánování a vlastní databáze. Google/Apple, obnova hesla a oznámení při zavřené aplikaci čekají na další zapojení. ${config.ai?'AI je připojená.':'AI fotografie zatím bez připojené služby.'}</p></div></div>`;
}
let priorFocus=null;
function modal(h,body,wide=false){priorFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(h)}"><div class="modal-header"><h2>${esc(h)}</h2><button data-action="close" aria-label="Zavřít">×</button></div>${body}</section></div>`;setTimeout(()=>$('.modal input,.modal button,.modal select')?.focus(),30);}
function closeModal(){$('#modal-root').innerHTML='';photoId=null;bodyPhotoId=null;priorFocus?.focus?.();}
const field=(label,name,value='',type='text',attrs='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const formEnd=(label='Uložit')=>`<p class="form-error hidden" role="alert"></p><div class="form-actions"><button type="submit" class="primary">${label} ${icon('check')}</button><button type="button" class="secondary" data-action="close">Zrušit</button></div>`;
function showExercise(id){const e=id?exercise(id):{name:'',plan,weight:0,extra:0,reps:8,mode:'machine',step:2.5,note:''};modal(id?'Upravit cvik':'Vlastní cvik',`<form data-form="exercise"><input type="hidden" name="id" value="${esc(id||'')}"><div class="form-grid"><div class="span2">${field('Název cviku / stroje','name',e.name,'text','required maxlength="80"')}</div>${field('Plán (např. Upper)','plan',e.plan,'text','required maxlength="40"')}${field('Přírůstek váhy (kg)','step',e.step,'number','min="0.1" max="100" step="0.1" required')}<label>Způsob zápisu<select name="mode">${[['machine','Stroj / celková váha'],['bar','Osa včetně kotoučů'],['single','Jedna činka / strana'],['added','Přídavná zátěž'],['stack','Celý zásobník · kg neznámé']].map(([v,l])=>`<option value="${v}" ${v===e.mode?'selected':''}>${l}</option>`).join('')}</select></label>${field('Výchozí opakování','reps',e.reps,'number','min="1" max="200" required')}${field('Základní váha (kg)','weight',e.weight,'number','min="0" max="2000" step="0.1" required')}${field('Přídavná váha (kg)','extra',e.extra,'number','min="0" max="2000" step="0.1" required')}<label class="span2">Poznámka / nastavení stroje<textarea name="note" maxlength="500">${esc(e.note)}</textarea></label></div>${formEnd()}</form>`);}
function showExerciseDetail(id){const e=exercise(id),sets=exSets(id),byDay=new Map();sets.filter(x=>!x.pending).slice().reverse().forEach(s=>{const d=new Date(s.created*1000).toLocaleDateString('sv-SE');byDay.set(d,Math.max(byDay.get(d)||0,e.mode==='stack'?s.reps:totalWeight(s)));});const best=sets.length?sets.reduce((a,b)=>totalWeight(b)>totalWeight(a)||totalWeight(b)===totalWeight(a)&&b.reps>a.reps?b:a):null;modal(e.name,`<p class="meta-line">${esc(e.note||'Vlastní cvik')} · ${esc(e.plan)}</p><div class="pr-grid"><div><small>Nejvyšší zapsaná zátěž</small><strong>${best?esc(performance(best,e)):'Zatím bez PR'}</strong></div><div><small>Celkem zapsáno</small><strong>${sets.length} sérií</strong></div></div>${chart([...byDay].slice(-30).map(([d,v])=>({label:dateText(d,true),value:v})),e.mode==='stack'?'opakování':'kg')}<div class="row"><button class="primary" data-action="log-set" data-id="${id}">Zapsat výkon ${icon('plus')}</button><button class="secondary" data-action="exercise" data-id="${id}">Upravit cvik</button></div><h3 class="section-gap">Historie sérií</h3>${sets.slice(0,50).map(s=>`<div class="history-row"><span>${dateText(s.created,true)} ${s.pending?'· čeká na uložžení':''}</span><b>${esc(performance(s,e))}${s.rpe?' · RPE '+s.rpe:''}</b><button class="ghost danger" data-action="delete-set" data-id="${s.id}" data-ex="${id}">Smazat</button></div>`).join('')||'<p class="muted">Výchozí hodnota plánu se nezapočítává jako osobní rekord.</p>'}`);}
async function ensureWorkout(){if(activeWorkout())return activeWorkout();const priority=chosenPriority(plan),exercise_order=orderExercises(state.exercises,plan,priority).map(e=>e.id);const w=await api('workout',{id:crypto.randomUUID(),name:plan,priority,exercise_order});state.workouts.unshift(w);saveCache();return w;}
async function showLogSet(id){const e=exercise(id);if(!e)return;await ensureWorkout();const last=lastFor(e),count=allSets().filter(s=>s.workout_id===activeWorkout()?.id&&s.exercise_id===id).length;modal(e.name,`<div class="set-last"><small>${exSets(id).length?'Poslední série':'Výchozí hodnota plánu'}</small><div><strong>${esc(performance(last,e))}</strong></div><p class="meta-line" style="margin:8px 0 0">${e.mode==='stack'?'Zkus přidat opakování.':`Další možný cíl: ${fmt(totalWeight(last),1)} kg × ${Number(last.reps)+1}. Přidej, až se na to cítíš.`}</p></div><form data-form="set"><input type="hidden" name="exercise_id" value="${id}"><div class="form-grid"><label class="span2">${e.mode==='single'?'Váha jedné činky / strany':'Základní váha'} (kg)<div class="value-stepper"><button type="button" data-action="step" data-field="weight" data-delta="-${e.step}">−</button><input name="weight" type="number" min="0" max="2000" step="0.1" value="${last.weight}" required ${e.mode==='stack'?'readonly':''}><button type="button" data-action="step" data-field="weight" data-delta="${e.step}" ${e.mode==='stack'?'disabled':''}>+</button></div></label>${Number(last.extra)||e.mode==='machine'?field('Přídavná zátěž (kg)','extra',last.extra||0,'number','min="0" max="2000" step="0.1"'):field('Přídavná zátěž (kg)','extra',0,'hidden')}<label class="${Number(last.extra)||e.mode==='machine'?'':'span2'}">Opakování<div class="value-stepper"><button type="button" data-action="step" data-field="reps" data-delta="-1">−</button><input name="reps" type="number" min="1" max="200" value="${last.reps}" required><button type="button" data-action="step" data-field="reps" data-delta="1">+</button></div></label><label>Náročnost RPE · volitelné<select name="rpe"><option value="">Bez hodnocení</option>${[6,7,8,9,10].map(n=>`<option value="${n}">${n}${n===10?' · žádné opakování navíc':n===9?' · 1 navíc':n===8?' · 2 navíc':''}</option>`).join('')}</select></label>${field('Poznámka k sérii','note','','text','maxlength="300"')}</div>${formEnd('Uložit '+(count+1)+'. sérii')}</form>`);}
function showMeal(m=null){photoId=m?.photo_id||null;modal('Přidat jídlo',`<div class="row wrap" style="margin-bottom:18px"><label class="secondary" style="color:var(--text);cursor:pointer">${icon('camera')} Vyfotit<input id="meal-file" type="file" accept="image/*" capture="environment" class="sr-only"></label><label class="secondary" style="color:var(--text);cursor:pointer">Z galerie<input id="meal-gallery" type="file" accept="image/*" class="sr-only"></label><button class="secondary" data-action="food-search">${icon('search')} Potraviny / kód</button></div><div id="photo-slot">${photoId?`<img class="photo-preview" src="/api/photo/${photoId}" alt="Fotografie jídla">`:''}</div><form data-form="meal"><div class="form-grid"><div class="span2">${field('Název jídla','name',m?.name||'','text','required maxlength="120" placeholder="Např. kuřecí s rýží"')}</div>${field('Kalorie celé porce (kcal)','kcal',m?.kcal??'','number','min="0" max="20000" step="0.1" required')}${field('Bílkoviny (g)','protein',m?.protein??'','number','min="0" max="2000" step="0.1" required')}${field('Sacharidy (g)','carbs',m?.carbs??'','number','min="0" max="3000" step="0.1" required')}${field('Tuky (g)','fat',m?.fat??'','number','min="0" max="2000" step="0.1" required')}<label class="span2">Popis porce / poznámka<textarea name="note" maxlength="1000" placeholder="Velká porce, přibližně 200 g rýže…">${esc(m?.note||'')}</textarea></label><label class="span2"><input name="favorite" type="checkbox" ${m?.favorite?'checked':''}> Uložit také mezi oblíbená jídla</label></div><div class="notice">Hodnoty zadávej pro celou snědenou porci. Odhad z fotografie před uložením zkontroluj.</div><button type="button" class="secondary full" data-action="analyze">${icon('bolt')} ${config.ai?'Odhadnout z fotografie pomocí AI':'AI zatím není připojená'}</button>${formEnd('Zapsat do deníku')}</form>`);}
function showSettings(){const s=state.user.settings;modal('Tvoje nastavení',`<form data-form="settings"><div class="form-grid"><div class="span2">${field('Přezdívka','name',state.user.name,'text','required maxlength="50"')}</div>${[['Denní kalorie','kcal',500,10000],['Bílkoviny (g)','protein',0,600],['Sacharidy (g)','carbs',0,1500],['Tuky (g)','fat',0,600],['Voda (ml)','water',0,10000],['Tréninky za týden','weekly',1,7],['Pauza mezi sériemi (s)','rest',15,600]].map(([label,key,min,max])=>field(label,key,s[key],'number',`min="${min}" max="${max}" required`)).join('')}${field('Čas připomínky','reminder_time',s.reminder_time,'time','required')}<label class="span2"><input name="share" type="checkbox" ${s.share?'checked':''}> Povolit sdílení tréninků s kamarády</label><label class="span2"><input name="gamification" type="checkbox" ${s.gamification?'checked':''}> Úrovně, odznaky a gamifikace</label><label class="span2"><input name="reminders" type="checkbox" ${s.reminders?'checked':''}> Jemná denní připomínka v otevřené aplikaci</label></div><div class="notice">Připomínky fungují pouze, když je aplikace otevřená. Při vypnutí sdílení se znepřístupní i dříve sdílené tréninky. Google a Apple přihlášení zatím nejsou připojené.</div>${formEnd()}</form>`);}
function showInstall(){modal('FORMA na ploše',`<h3>iPhone · Safari</h3><ol class="install-steps"><li>Otevři adresu aplikace v <b>Safari</b>.</li><li>Klepni na <b>Sdílet</b> (čtvereček se šipkou nahoru; podle verze může být v nabídce dalších možností).</li><li>Vyber <b>Přidat na plochu</b>.</li><li>Pokud se zobrazí volba <b>Otevřít jako webovou aplikaci</b>, nech ji zapnutou.</li><li>Potvrď název FORMA a klepni na <b>Přidat</b>.</li></ol><h3>Android · Chrome</h3><p>Otevři nabídku ⋮ → Přidat na plochu / Nainstalovat aplikaci.</p><div class="notice warning">Pro instalaci a offline režim na telefonu potřebuješ nasazení na HTTPS adrese. Adresa localhost z Macu na iPhonu nefunguje. V této dodávce není veřejné nasazení dokončené.</div><p class="meta-line">Data účtu se ukládají na server. Při jeho změně se nepřenesou automaticky; provozovatel musí přenést databázi.</p>`);}
function showHistory(){modal('Historie tréninků',completed().map(w=>`<button class="history-row full" data-action="workout-detail" data-id="${w.id}"><span><b>${esc(w.name)}</b><small style="display:block">${dateText(w.started)}</small></span><span>${allSets().filter(s=>s.workout_id===w.id).length} sérií ↗</span></button>`).join('')||empty('První trénink tě čeká','Dokončené tréninky a jejich série uvidíš tady.'));}
async function loadCommunity(){community=await api('community');if(tab==='friends'||tab==='profile')render();}
async function photoUpload(file,kind='meal'){
 if(!file)return null;
 if(file.size>20_000_000)throw new Error('Vyber fotografii menší než 20 MB.');
 const url=URL.createObjectURL(file);let blob;
 try{const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('Fotku nelze načíst. Použij JPG nebo PNG.'));i.src=url;});const scale=Math.min(1,1280/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.78));}finally{URL.revokeObjectURL(url);}
 if(!blob)throw new Error('Nepodařilo se připravit fotografii.');
 const form=new FormData();form.append('file',blob,'photo.jpg');form.append('kind',kind);return (await api('photo',form)).id;
}
function timerRender(){document.querySelector('.timer-bar')?.remove();if(restEnd<=Date.now())return;const left=Math.ceil((restEnd-Date.now())/1000);document.body.insertAdjacentHTML('beforeend',`<div class="timer-bar"><span>${icon('clock')} Pauza</span><b>${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}</b><button data-action="timer-add" aria-label="Přidat 30 sekund">+30</button><button data-action="timer-stop" aria-label="Zastavit časovač">×</button></div>`);}
function formError(form,e){const el=form.querySelector('.form-error');if(el){el.textContent=e.network?'Bez připojení. Tato změna potřebuje server.':e.message;el.classList.remove('hidden');}else toast(e.message);}

document.addEventListener('click',async ev=>{
 const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 try{
  if(a==='auth-switch'){authRegister=!authRegister;return renderAuth();}
  if(a==='close')return closeModal();
  if(a==='install')return showInstall();
  if(a==='tab'){tab=id;render();if(id==='friends')await loadCommunity();if(id==='profile')loadCommunity().catch(()=>{});return;}
  if(a==='template'){await api('template',{});await refresh();tab='train';render();return toast('Upper / Lower je připravený. Váhy si před cvičením uprav.');}
  if(a==='plan'){plan=id;return render();}
  if(a==='priority'){selectedPriorities[b.dataset.plan]=id;return render();}
  if(a==='open-plan'){plan=id;tab='train';render();return;}
  if(a==='exercise')return showExercise(id);
  if(a==='exercise-detail')return showExerciseDetail(id);
  if(a==='start'){await ensureWorkout();render();return toast('Trénink začíná. Vlastním tempem.');}
  if(a==='log-set')return await showLogSet(id);
  if(a==='step'){const input=$(`.modal input[name="${b.dataset.field}"]`);if(input&&!input.readOnly)input.value=Math.min(Number(input.max),Math.max(Number(input.min),Math.round((Number(input.value)+Number(b.dataset.delta))*10)/10));return;}
  if(a==='finish'){
   if(queue().length){await sync();if(queue().length)throw new Error('Nejdřív synchronizuj čekající série. Trénink zatím zůstává otevřený.');}
   return modal('Dobrý trénink.',`<form data-form="finish"><p>Zapsal jsi ${allSets().filter(s=>s.workout_id===activeWorkout().id).length} sérií. Hotové výkony zůstanou v historii.</p>${state.user.settings.share?'<label><input type="checkbox" name="shared"> Sdílet tento trénink s kamarády</label>':'<div class="notice">Trénink bude soukromý. Sdílení můžeš povolit v profilu.</div>'}${formEnd('Dokončit trénink')}</form>`);
  }
  if(a==='history')return showHistory();
  if(a==='workout-detail'){const w=state.workouts.find(w=>w.id===id);return modal(w.name,`<p class="muted">${dateText(w.started)} · ${w.ended?Math.max(1,Math.round((w.ended-w.started)/60))+' min':'Rozpracováno'} · ${w.shared?'Sdílený':'Soukromý'}</p>${allSets().filter(s=>s.workout_id===id).reverse().map(s=>`<div class="history-row"><span>${esc(exercise(s.exercise_id)?.name)}</span><b>${esc(performance(s,exercise(s.exercise_id)))}</b></div>`).join('')||'<p class="muted">Bez zapsaných sérií.</p>'}`);}
  if(a==='delete-set'){if(!confirm('Smazat tuto sérii?'))return;const pending=queue().find(s=>s.id===id);if(pending)localStorage.setItem(queueKey(state.user.id),JSON.stringify(queue().filter(s=>s.id!==id)));else await api('set/delete',{id});await refresh();render();return showExerciseDetail(b.dataset.ex);}
  if(a==='timer-add'){restEnd+=30000;return timerRender();}
  if(a==='timer-stop'){restEnd=0;return timerRender();}
  if(a==='sync'){await sync();return render();}
  if(a==='water'){await api('water',{day:today(),ml:Math.max(0,waterToday()+Number(b.dataset.ml))});await refresh();return render();}
  if(a==='meal'||a==='meal-photo'){showMeal();if(a==='meal-photo')$('#meal-file').click();return;}
  if(a==='day'){const d=new Date(selectedDay+'T12:00:00');d.setDate(d.getDate()+Number(id));selectedDay=d.toLocaleDateString('sv-SE');return render();}
  if(a==='analyze'){
   if(!config.ai)throw new Error('AI ještě není připojená. Fotku můžeš uložit s ručně zadanými hodnotami.');if(!photoId)throw new Error('Nejdřív vyber fotografii.');
   if(!confirm('Odeslat tuto fotografii a popis porce službě OpenAI pro odhad živin?'))return;
   b.disabled=true;b.textContent='Odhaduji porci…';try{const r=await api('analyze',{photo_id:photoId,description:$('.modal [name="note"]').value.slice(0,600)});for(const k of ['name','kcal','protein','carbs','fat','note'])$('.modal [name="'+k+'"]').value=r[k];toast('Odhad připravený. Zkontroluj porci a složení.');}finally{b.disabled=false;b.textContent='Odhadnout z fotografie pomocí AI';}return;
  }
  if(a==='meal-detail'){const m=state.meals.find(m=>m.id===id);return modal(m.name,`${m.photo_id?`<img class="photo-preview" src="/api/photo/${m.photo_id}" alt="Fotografie jídla">`:''}<div class="number section-gap">${fmt(m.kcal)}<small> kcal</small></div><p>Bílkoviny ${fmt(m.protein)} g · sacharidy ${fmt(m.carbs)} g · tuky ${fmt(m.fat)} g</p><p class="muted">${esc(m.note)}</p><div class="row"><button class="secondary" data-action="meal-copy" data-id="${id}">Použít znovu</button><button class="ghost danger" data-action="meal-delete" data-id="${id}">Smazat záznam</button></div>`);}
  if(a==='meal-copy'){const m=state.meals.find(m=>m.id===id);return showMeal(m);}
  if(a==='meal-delete'){if(!confirm('Smazat jídlo z deníku?'))return;await api('meal/delete',{id});await refresh();closeModal();return render();}
  if(a==='favorites'){const favorites=state.meals.filter(m=>m.favorite);const unique=[...new Map(favorites.map(m=>[m.name,m])).values()];return modal('Oblíbená jídla',unique.map(m=>`<button class="food-result" data-action="meal-copy" data-id="${m.id}"><b>${esc(m.name)}</b><small>${fmt(m.kcal)} kcal · B ${fmt(m.protein)} g</small></button>`).join('')||empty('Tvoje rychlé volby','Při přidávání jídla zaškrtni uložení mezi oblíbené.'));}
  if(a==='copy-meals'){const d=new Date(selectedDay+'T12:00:00');d.setDate(d.getDate()-1);const meals=state.meals.filter(m=>m.day===d.toLocaleDateString('sv-SE'));return modal('Vyber včerejší jídlo',meals.map(m=>`<button class="food-result" data-action="meal-copy" data-id="${m.id}"><b>${esc(m.name)}</b><small>${fmt(m.kcal)} kcal</small></button>`).join('')||empty('Včera je prázdno','Pro tento den nejsou žádná jídla k převzetí.'));}
  if(a==='food-search')return modal('Najít potravinu',`<form data-form="food-search"><label>Název nebo čárový kód<input name="query" required minlength="2" placeholder="Skyr / 859…" autocomplete="off"></label>${formEnd('Hledat')}</form><div id="food-results"></div><p class="meta-line section-gap">Open Food Facts · hodnoty na 100 g, ověř etiketu. Čárový kód v této verzi napiš ručně.</p>`);
  if(a==='pick-food'){const p=JSON.parse(b.dataset.food);return modal(p.name,`<form data-form="portion"><input type="hidden" name="food" value="${esc(JSON.stringify(p))}">${field('Snědené množství (g)','grams',100,'number','min="1" max="10000" required')}<p class="meta-line section-gap">Na 100 g: ${fmt(p.kcal)} kcal · B ${fmt(p.protein)} · S ${fmt(p.carbs)} · T ${fmt(p.fat)} g</p>${formEnd('Použít porci')}</form>`);}
  if(a==='metric')return modal('Tělesný progres',`<form data-form="metric"><div class="form-grid">${field('Datum','day',today(),'date','required')}${field('Hmotnost (kg)','weight','','number','min="20" max="500" step="0.1"')}${field('Obvod pasu (cm) · volitelné','waist','','number','min="20" max="300" step="0.1"')}<label>Soukromá fotografie<input type="file" id="body-file" accept="image/*"></label></div><div id="body-photo-status" class="meta-line section-gap"></div>${formEnd()}</form>`);
  if(a==='view-photo')return modal('Soukromá fotografie',`<img src="/api/photo/${id}" alt="Fotografie tělesného progresu" style="width:100%;border-radius:16px">`);
  if(a==='settings')return showSettings();
  if(a==='plates')return modal('Kalkulačka kotoučů',`<form data-form="plates"><div class="form-grid">${field('Celková cílová váha (kg)','target',100,'number','min="0" max="1000" step="0.5" required')}${field('Váha osy (kg)','bar',20,'number','min="0" max="100" step="0.5" required')}</div>${formEnd('Spočítat')}</form><div id="plate-result"></div><p class="meta-line section-gap">Počítá kotouče 25 / 20 / 15 / 10 / 5 / 2,5 / 1,25 kg v neomezeném počtu. Výsledek je pro jednu stranu osy.</p>`);
  if(a==='recipe')return modal('Vlastní recept',`<form data-form="recipe">${field('Název receptu','name','','text','required maxlength="120"')}<label class="section-gap">Suroviny a výživové hodnoty<textarea name="ingredients" rows="5" required placeholder="Jedna surovina na řádek: název; kcal; bílkoviny; sacharidy; tuky&#10;Rýže 200 g; 260; 5; 56; 1"></textarea></label><p class="meta-line">Vyplň hodnoty pro použité množství každé suroviny. Odděluj středníkem.</p>${field('Počet porcí','portions',1,'number','min="1" max="100" required')}${formEnd('Připravit jednu porci')}</form>`);
  if(a==='challenge'){const end=new Date();end.setDate(end.getDate()+6);return modal('Společná výzva',`<form data-form="challenge">${field('Název','title','Týden pro sebe','text','required maxlength="80"')}<div class="form-grid section-gap">${field('Od','start',today(),'date','required')}${field('Do (včetně)','end',end.toLocaleDateString('sv-SE'),'date','required')}${field('Cíl tréninků na osobu','target',3,'number','min="1" max="100" required')}</div><div class="notice">Zapojením souhlasíš se sdílením počtu dokončených tréninků v období výzvy. Podrobnosti soukromých tréninků zůstanou skryté. Kamarádi se přidávají dobrovolně.</div>${formEnd('Vytvořit a přidat se')}</form>`);}
  if(a==='challenge-join'||a==='challenge-leave'){if(a==='challenge-join'&&!confirm('Sdílet s účastníky výzvy počet dokončených tréninků v jejím období? Detaily soukromých tréninků se nesdílí.'))return;await api(a==='challenge-join'?'challenge/join':'challenge/leave',{id});return await loadCommunity();}
  if(a==='load-community')return await loadCommunity();
  if(a==='invite'){const link=location.origin+'/?invite='+encodeURIComponent(state.user.code);return modal('Pozvi svoji partu',`<p>Kamarád si vytvoří vlastní účet a pozvánku přijme. Uvidíte jen dobrovolně sdílené tréninky.</p><div class="inline-code" id="invite-link">${esc(link)}</div><button class="primary full section-gap" data-action="copy-invite">Zkopírovat odkaz</button><div class="notice">Kód pozvánky: <b>${esc(state.user.code)}</b><br>Odkaz funguje pro ostatní až na veřejné adrese.</div>`);}
  if(a==='copy-invite'){try{await navigator.clipboard.writeText($('#invite-link').textContent);toast('Odkaz zkopírovaný.');}catch{toast('Označ a zkopíruj odkaz nad tlačítkem.');}return;}
  if(a==='join')return modal('Přijmout pozvánku',`<form data-form="join">${field('Kód nebo celý odkaz','code','','text','required maxlength="300"')}${formEnd('Přidat kamaráda')}</form>`);
  if(a==='remove-friend'){if(!confirm('Odebrat kamaráda? Přestanete si vidět sdílené tréninky.'))return;await api('friend/remove',{id});return await loadCommunity();}
  if(a==='react'){await api('reaction',{workout_id:id});return await loadCommunity();}
  if(a==='comment')return modal('Podpoř kamaráda',`<form data-form="comment"><input type="hidden" name="workout_id" value="${id}"><label>Komentář<textarea name="text" maxlength="300" required></textarea></label>${formEnd('Přidat komentář')}</form>`);
  if(a==='copy-workout'){const w=community.feed.find(w=>w.id===id),seen=new Set();for(const s of w.sets){if(seen.has(s.name))continue;seen.add(s.name);await api('exercise',{name:s.name,plan:w.name+' · '+w.author,weight:s.weight,extra:s.extra,reps:s.reps,mode:s.mode,step:2.5,note:'Převzato od '+w.author});}await refresh();plan=w.name+' · '+w.author;tab='train';render();return toast('Plán je ve tvých trénincích.');}
  if(a==='logout'){if(queue().length&&!confirm('Čekající offline série nebudou odhlášením synchronizované. Přesto pokračovat?'))return;await api('logout',{});localStorage.removeItem(cacheKey(state.user.id));localStorage.removeItem('forma-last-user');state=null;community=null;closeModal();return renderAuth();}
  if(a==='delete-account')return modal('Smazat účet',`<form data-form="delete-account"><p>Tím smažeš účet, tréninky, jídla i fotografie. Tuto akci nelze vrátit.</p>${field('Pro potvrzení napiš SMAZAT','confirm','','text','required pattern="SMAZAT"')}${formEnd('Trvale smazat účet')}</form>`);
 }catch(e){toast(e.network?'Bez připojení. Zkus to znovu online.':e.message);}
});
document.addEventListener('submit',async ev=>{
 const form=ev.target.closest('[data-form]');if(!form)return;ev.preventDefault();const action=form.dataset.form,data=Object.fromEntries(new FormData(form)),button=form.querySelector('[type="submit"]');if(button.disabled)return;button.disabled=true;
 try{
  if(action==='auth'){await api(authRegister?'register':'login',data);await refresh();render();await acceptInvite();return;}
  if(action==='exercise'){await api('exercise',data);await refresh();plan=data.plan;tab='train';closeModal();render();return toast('Cvik uložený.');}
  if(action==='set'){
   const payload={...data,id:crypto.randomUUID(),workout_id:activeWorkout().id,created:Math.floor(Date.now()/1000),weight:Number(data.weight),extra:Number(data.extra||0),reps:Number(data.reps)};
   let pending=false;
   try{await api('set',payload);}catch(e){if(!e.network)throw e;localStorage.setItem(queueKey(state.user.id),JSON.stringify([...queue(),payload]));pending=true;offline=true;}
   if(!pending){state.sets.unshift({...payload,user_id:state.user.id});const e=exercise(payload.exercise_id);Object.assign(e,{weight:payload.weight,extra:payload.extra,reps:payload.reps});saveCache();refresh().catch(()=>{});}else saveCache();
   restEnd=Date.now()+Number(state.user.settings.rest)*1000;closeModal();render();return toast(pending?'Série uložená v zařízení. Čeká na připojení.':'Série uložená. Dej si pauzu.');
  }
  if(action==='finish'){await api('workout/finish',{id:activeWorkout().id,shared:!!data.shared});await refresh();tab='home';closeModal();render();return toast(state.user.settings.gamification?'Hotovo. Další krok za tebou. +100 XP':'Trénink dokončený.');}
  if(action==='meal'){await api('meal',{...data,id:crypto.randomUUID(),day:selectedDay,photo_id:photoId,favorite:!!data.favorite});await refresh();closeModal();tab='food';render();return toast('Jídlo zapsané.');}
  if(action==='settings'){await api('settings',{...data,share:!!data.share,gamification:!!data.gamification,reminders:!!data.reminders});await refresh();closeModal();render();return toast('Nastavení uložené.');}
  if(action==='metric'){if(!data.weight&&!data.waist&&!bodyPhotoId)throw new Error('Vyplň váhu, míru nebo přidej fotografii.');await api('metric',{...data,photo_id:bodyPhotoId});await refresh();closeModal();render();return toast('Progres uložený.');}
  if(action==='food-search'){
   const q=data.query.trim(),r=await api('foods?'+(/^\d{8,14}$/.test(q)?'barcode=':'q=')+encodeURIComponent(q));$('#food-results').innerHTML=r.products.map(p=>`<button class="food-result" data-action="pick-food" data-food="${esc(JSON.stringify(p))}"><b>${esc(p.name)}</b><small>${esc(p.brand)} · ${fmt(p.kcal)} kcal / 100 g</small></button>`).join('')||'<p class="muted section-gap">Potravina nenalezena. Zkus jiný název nebo ruční zápis.</p>';return;
  }
  if(action==='portion'){const p=JSON.parse(data.food),scale=Number(data.grams)/100;['kcal','protein','carbs','fat'].forEach(k=>p[k]=Math.round(p[k]*scale*10)/10);p.note=`${data.grams} g · Open Food Facts; zkontroluj etiketu.`;return showMeal(p);}
  if(action==='plates'){let remaining=(Number(data.target)-Number(data.bar))/2;if(remaining<0)throw new Error('Cílová váha musí být alespoň váha osy.');const parts=[];for(const kg of [25,20,15,10,5,2.5,1.25]){const n=Math.floor((remaining+.00001)/kg);if(n)parts.push(n+'× '+fmt(kg,2)+' kg');remaining-=n*kg;}$('#plate-result').innerHTML=`<div class="notice"><b>Na každou stranu:</b><br>${parts.join(' + ')||'Bez kotoučů'}${remaining>.001?'<br>Tuto váhu nelze přesně sestavit. Zbývá '+fmt(remaining,2)+' kg na stranu.':''}</div>`;return;}
  if(action==='recipe'){const totals={kcal:0,protein:0,carbs:0,fat:0};const lines=data.ingredients.split('\n').filter(x=>x.trim());for(const line of lines){const fields=line.split(';').map(s=>s.trim());if(fields.length!==5)throw new Error('Každý řádek musí mít název a čtyři hodnoty oddělené středníkem.');for(const [i,key] of ['kcal','protein','carbs','fat'].entries()){const n=Number(fields[i+1].replace(',','.'));if(!Number.isFinite(n)||n<0)throw new Error('Suroviny musí mít nezáporné číselné hodnoty.');totals[key]+=n;}}for(const k in totals)totals[k]=Math.round(totals[k]/Number(data.portions)*10)/10;return showMeal({...totals,name:data.name,favorite:true,note:'1 z '+data.portions+' porcí.\n'+data.ingredients});}
  if(action==='challenge'){const start=new Date(data.start+'T00:00:00'),end=new Date(data.end+'T00:00:00');end.setDate(end.getDate()+1);if(end<=start)throw new Error('Konec výzvy musí být po začátku.');await api('challenge',{title:data.title,target:Number(data.target),started:Math.floor(start.getTime()/1000),ends:Math.floor(end.getTime()/1000)});closeModal();return await loadCommunity();}
  if(action==='join'){let code=data.code.trim();if(code.startsWith('http')){try{code=new URL(code).searchParams.get('invite')||'';}catch{throw new Error('Neplatná pozvánka.');}}await api('friend',{code});closeModal();tab='friends';await loadCommunity();return toast('Kamarád přidaný.');}
  if(action==='comment'){await api('comment',data);closeModal();return await loadCommunity();}
  if(action==='delete-account'){const id=state.user.id;await api('account/delete',data);localStorage.removeItem(cacheKey(id));localStorage.removeItem(queueKey(id));localStorage.removeItem('forma-last-user');state=null;community=null;closeModal();renderAuth();return toast('Účet a data byly smazány.');}
 }catch(e){formError(form,e);}finally{if(button.isConnected)button.disabled=false;}
});
document.addEventListener('change',async ev=>{
 const el=ev.target;
 if(el.id==='food-day'){selectedDay=el.value||today();return render();}
 if(['meal-file','meal-gallery','body-file'].includes(el.id)){
  const form=el.closest('.modal')?.querySelector('form'),btn=form?.querySelector('[type="submit"]');if(btn)btn.disabled=true;
  try{toast('Připravuji fotografii…');if(el.id==='body-file'){bodyPhotoId=await photoUpload(el.files[0],'body');$('#body-photo-status').textContent='Soukromá fotografie je připravená.';}else{photoId=await photoUpload(el.files[0]);$('#photo-slot').innerHTML=`<img class="photo-preview" src="/api/photo/${photoId}" alt="Fotografie jídla">`;toast('Fotka připravená. Vyplň hodnoty nebo spusť AI.');}}
  catch(e){toast(e.message);}finally{if(btn)btn.disabled=false;}
 }
});
document.addEventListener('keydown',ev=>{
 if(!$('.modal'))return;
 if(ev.key==='Escape'){closeModal();return;}
 if(ev.key==='Tab'){const f=[...$('.modal').querySelectorAll('button:not(:disabled),input:not([type=hidden]),select,textarea,a[href]')].filter(x=>x.offsetParent!==null);if(!f.length)return;const first=f[0],last=f[f.length-1];if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}
});
async function acceptInvite(){const code=new URL(location.href).searchParams.get('invite');if(!code||!state)return;modal('Pozvánka do party',`<p>Chceš přijmout pozvánku a propojit se s kamarádem? Soukromé údaje zůstanou soukromé.</p><form data-form="join"><input type="hidden" name="code" value="${esc(code)}">${formEnd('Přijmout pozvánku')}</form>`);history.replaceState(null,'',location.pathname);}
window.addEventListener('online',async()=>{try{await sync();await refresh();render();}catch{}});
window.addEventListener('offline',()=>{offline=true;if(state)render();});
setInterval(()=>{const had=restEnd>0;timerRender();if(had&&restEnd<=Date.now()){restEnd=0;toast('Pauza skončila. Pokračuj, až budeš připravený.');}if(!state)return;const s=state.user.settings,now=new Date(),hm=now.toLocaleTimeString('cs-CZ',{hour:'2-digit',minute:'2-digit',hour12:false});if(s.reminders&&hm===s.reminder_time&&lastReminder!==today()){lastReminder=today();toast('Malá připomínka: mrkni na svůj dnešní plán.');}},1000);
(async()=>{
 try{config=await api('config');}catch{}
 try{await refresh();await sync();render();await acceptInvite();}
 catch(e){if(e.network){try{const id=localStorage.getItem('forma-last-user');state=JSON.parse(localStorage.getItem(cacheKey(id))||'null');offline=true;render();}catch{renderAuth();}}else renderAuth();}
 if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
})();
